const App = () => {
  const [checked, setChecked] = useState(false);
  const [submitted, setSubmitted] = useState(false);
  const [error, setError] = useState(null);
  const checkboxRef = useRef(null);

  const handleSubmit = (e) => {
    e.preventDefault();
    if (!checked) {
      setError("You must agree to the Terms of Use to continue.");
      checkboxRef.current?.focus();
    } else {
      setError(null);
      setSubmitted(true);
    }
  };

  if (submitted) {
    return (
      <main>
        <div role="status" aria-live="polite" className="success-message">
          <h2>Submission Received</h2>
          <p>Thank you for agreeing to our Terms of Use. Your consent has been successfully recorded.</p>
        </div>
      </main>
    );
  }

  return (
    <main>
      <h1>Consent Form</h1>
      <form onSubmit={handleSubmit} noValidate>
        <div className="form-field">
          <div className="checkbox-wrapper">
            <input
              type="checkbox"
              id="terms-consent"
              name="terms-consent"
              required
              checked={checked}
              onChange={(e) => {
                setChecked(e.target.checked);
                if (e.target.checked) setError(null);
              }}
              aria-describedby={`terms-help ${error ? "terms-error" : ""}`}
              aria-invalid={!!error}
              ref={checkboxRef}
            />
            <label htmlFor="terms-consent">
              I agree to the <a href="#terms" onClick={(e) => e.preventDefault()}>Terms of Use</a>
              <span className="required-marker" aria-hidden="true"> *</span>
            </label>
          </div>

          <p id="terms-help" className="helper-text">
            Required for account activation.
          </p>

          {error && (
            <p id="terms-error" className="error-text">
              <span aria-hidden="true">Error:</span> {error}
            </p>
          )}
        </div>

        <button type="submit">
          Continue
        </button>
      </form>
    </main>
  );
};

const root = ReactDOM.createRoot(document.getElementById('root'));
root.render(<App />);
